fn solve(n: i8, s: Vec<char>) -> i8 {
    // Requires: n must be non-negative and the length of s must be equal to n
    // Ensures: The return value is the count of adjacent equal-character pairs in s
    // Decreases: n, as we iterate from 0 to n-1
    // Invariant: At each step, count is the number of adjacent equal-character pairs found so far
    //           and 0 <= i < n - 1
    //           s is a vector of characters of length n

    assert!(n >= 0);
    assert!(s.len() as i8 == n);

    let mut count = 0;

    // Loop invariant: count is the number of adjacent equal-character pairs found so far
    //                and 0 <= i < n - 1
    for i in 0..(n - 1) {
        // Assert that i is within bounds
        assert!(i >= 0 && i < n - 1);
        
        // Check if the current character is equal to the next character
        if s[i as usize] == s[(i + 1) as usize] {
            count += 1;
        }
    }

    // Ensures that the count is the correct number of adjacent equal-character pairs
    count
}